rules = Rule @@@ counts;

(* build a grid of frequencies *)
grid = ConstantArray[0, {Max[coords[[All, 1]]], Max[coords[[All, 2]]]}];
Do[
  grid[[coord[[1]], coord[[2]]]] = n,
  { {coord, n}, counts }
];

ArrayPlot[grid, ColorFunction -> "Rainbow"]
```

