```wl
coords = {{1,2}, {2,3}, {1,2}, {4,1}, {2,3}, {2,3}, {3,3}};

heat = SparseArray[Rule @@@ Tally[coords]];

ArrayPlot[Normal[heat], ColorFunction -> "Rainbow"]
```

