A convenient way is to approximate the circle by many points, evolve each point under the flow, and then reconnect the evolved points as a polygon.

Here is a version based on the resolved approach:

```wl
splot = StreamPlot[{y, -Sin[x]}, {x, -4, 4}, {y, -3, 3},
   StreamColorFunction -> "Rainbow"];

flow = Function[{t, a, b},
   Evaluate[{x[t, a, b], y[t, a, b]} /. 
     First @ NDSolve[
       {D[x[t, a, b], t] == y[t, a, b],
        D[y[t, a, b], t] == -Sin[x[t, a, b]],
        x[0, a, b] == a,
        y[0, a, b] == b},
       {x, y}, {t, 0, 20},
       {a, -1/2, 1/2}, {b, 1/2, 3/2}
     ]],
   Listable];

circlePts = With[{n = 100},
   Table[{0., 1.} + {Cos[t], Sin[t]}/2, 
    {t, 0, 2 Pi - 2 Pi/n, 2 Pi/n}]
];

Manipulate[
 Show[
  splot,
  Graphics[
   GraphicsComplex[
    Dynamic @ flow[t, circlePts[[All, 1]], circlePts[[All, 2]]],
    {Opacity[0.6], Red, Polygon[Range @ Length @ circlePts]}
   ]
  ],
  AspectRatio -> Automatic
 ],
 {t, 0., 20.}
]
```

What this does:
