data = Reap[
   ParametricPlot3D[Sow[pf], {u, 0, 2 Pi}, {v, -Pi, Pi}]
][[2, 1]];

Keep only numeric 3D points:
pts = Cases[data, {_?NumericQ, _?NumericQ, _?NumericQ}];
