A clean way is to use `Checkbox` for the on/off state and `RadioButtonBar` for the choice between variants, all inside `Manipulate`. You can also use `Enabled -> Dynamic[...]` so the radio buttons only work when that section is checked.

Here is a simple pattern for a control array of buttons/toggles:

```wl
Manipulate[
 Plot[If[auOn, auVal, 0] + If[tuOn, tuVal, 0], {p, 0, 1},
  PlotStyle -> Thick,
  Frame -> True,
  ImagePadding -> 40
 ],
 Grid[{
   {
    Grid[{
      {Row[{
         "AU ",
         Checkbox[Dynamic[auOn]]
       }]},
      {RadioButtonBar[
        Dynamic[auVal],
        {Exp[-p] -> "AU1", 3 p -> "AU2"},
        Appearance -> "Vertical",
        Enabled -> Dynamic[auOn]
      ]}
    }, Alignment -> Center, Spacings -> 0],

    Grid[{
      {Row[{
         "TU ",
         Checkbox[Dynamic[tuOn]]
       }]},
      {RadioButtonBar[
        Dynamic[tuVal],
        {-4 (p - 3) -> "TU1", 3 -> "TU2"},
        Appearance -> "Vertical",
        Enabled -> Dynamic[tuOn]
      ]}
    }, Alignment -> Center, Spacings -> 0]
   }
 }],
 {{auOn, True}, None},
 {{tuOn, True}, None},
 {{auVal, Exp[-p]}, None},
 {{tuVal, -4 (p - 3)}, None}
]
```

