```wl
flake := Module[{arm},
  arm = Accumulate[{{0, 0.1}} ~Join~ RandomReal[{-1, 1}, {5, 2}]];
  arm = arm.Transpose@RotationMatrix[{arm[[-1]], {0, 1}}];
  arm = arm ~Join~ Rest@Reverse[arm . {{-1, 0}, {0, 1}}];
  Polygon[Flatten[arm . RotationMatrix[# Pi/3] & /@ Range[6], 1]]
]
