Graphics3D[
 {
  Text[Style["X", 25, Bold], {pr[[1, 2]] (1 + pad), 0, 0}],
  Text[Style["Y", 25, Bold], {0, pr[[2, 2]] (1 + pad), 0}],
  Text[Style["Z", 25, Bold], {0, 0, pr[[3, 2]] (1 + pad)}]
 },
