For a general parametric curve `r[t]`, you can do:

```wl
Manipulate[
 Module[{p, v},
  p = {Cos[a], Sin[a]};
  v = {-Sin[a], Cos[a]}; (* derivative *)

  Show[
   ParametricPlot[{Cos[t], Sin[t]}, {t, 0, 2 Pi},
    PlotRange -> 1.5],
   Graphics[{
     Blue, PointSize[Large], Point[p],
     Red, Thick, Arrow[{p - 0.5 v, p + 0.5 v}]
   }]
  ]
 ],
 {a, 0, 2 Pi}
]
```

If you want the tangent as a line segment instead of an arrow:

```wl
Manipulate[
 Module[{p, v},
  p = {Cos[a], Sin[a]};
  v = {-Sin[a], Cos[a]};

  Show[
   ParametricPlot[{Cos[t], Sin[t]}, {t, 0, 2 Pi},
    PlotRange -> 1.5],
   Graphics[{
     Blue, PointSize[Large], Point[p],
     Red, Thick, Line[{p - 0.5 v, p + 0.5 v}]
   }]
  ]
 ],
 {a, 0, 2 Pi}
]
```

