```wolfram
SeedRandom[1];

arm = Table[
   {t Cos[Pi/6], t Sin[Pi/6]} + 0.05 RandomReal[{-1, 1}, 2],
   {t, 0, 1, 0.02}
];

snowflake = Graphics[
  Table[
   Rotate[Line[arm], k Pi/3],
   {k, 0, 5}
  ],
  PlotRange -> All,
  ImageSize -> 300
];
```

